@Test
public void testGetParameterValues() {
    Set<String> expectedSet;
    Set<String> actualSet;
    expectedSet = new HashSet<String>(Arrays.asList("red", "green", "blue", "yellow"));
    actualSet = new HashSet<String>(Arrays.asList(request.getParameterValues("color")));
    Assert.assertEquals("color", expectedSet, actualSet);
    expectedSet = new HashSet<String>(Arrays.asList("Amsterdam", "Bonn", "Pisa"));
    actualSet = new HashSet<String>(Arrays.asList(request.getParameterValues("city")));
    Assert.assertEquals("city", expectedSet, actualSet);
    expectedSet = new HashSet<String>(Arrays.asList("Trinidad & Tobago"));
    actualSet = new HashSet<String>(Arrays.asList(request.getParameterValues("country")));
    Assert.assertEquals("country", expectedSet, actualSet);
